// Colour presets (src/lib/styles/palettes.json, generated by tools/make-palettes.mjs).
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';

const pal = JSON.parse(fs.readFileSync(new URL('../src/lib/styles/palettes.json', import.meta.url), 'utf8'));
const hex = /^#[0-9a-f]{6}$/;
const lin = (c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const lum = (h) => [1, 3, 5].map((i) => lin(parseInt(h.slice(i, i + 2), 16) / 255)).reduce((s, v, i) => s + v * [0.2126, 0.7152, 0.0722][i], 0);
const contrast = (a, b) => {
  const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
};

test('ten presets with unique ids, the default among them', () => {
  assert.equal(pal.presets.length, 10);
  assert.equal(new Set(pal.presets.map((p) => p.id)).size, 10);
  assert.ok(pal.presets.some((p) => p.id === pal.default));
  for (const p of pal.presets) assert.ok(p.name.uk && p.name.en, p.id);
});

test('every preset: 7-step ramps, 8 series colours, readable accent, both themes', () => {
  const surface = { light: '#ffffff', dark: '#161b21' };
  for (const p of pal.presets) {
    for (const mode of ['light', 'dark']) {
      const m = p[mode];
      assert.equal(m.seq.length, 7, `${p.id} ${mode} seq`);
      assert.equal(m.seqOn.length, 7);
      assert.equal(m.cat.length, 8);
      for (const c of [...m.seq, ...m.seqOn, ...m.cat, m.accent, m.sel]) assert.match(c, hex, `${p.id} ${mode} ${c}`);
      // lightness moves away from the surface as the value grows
      const L = m.seq.map(lum);
      for (let i = 1; i < 7; i++) assert.ok(mode === 'light' ? L[i] < L[i - 1] : L[i] > L[i - 1], `${p.id} ${mode} step ${i + 1}`);
      // text on each step and the accent stay readable
      m.seq.forEach((c, i) => assert.ok(contrast(c, m.seqOn[i]) >= 4.5, `${p.id} ${mode} text on step ${i + 1}`));
      assert.ok(contrast(m.accent, surface[mode]) >= 4.5, `${p.id} ${mode} accent`);
      // series colours are the validated set, just rotated
      assert.equal(new Set(m.cat).size, 8);
    }
  }
});
